       <include refid=\"AuditEventColumns\"/>\n        FROM app.audit_event\n        WHERE tenant_id = #{tenantId, javaType=java.util.UUID, jdbcType=OTHER}\n          AND event_time &gt;= #{fromTime}\n          AND event_time &lt;  #{toTime}\n\n        <if test=\"caseId != null\">\n            AND case_id = #{caseId, javaType=java.util.UUID, jdbcType=OTHER}\n        </if>\n\n        <if test=\"eventType != null and eventType != ''\">\n            AND event_type = #{eventType}\n        </if>\n\n        <if test=\"cursorEventTime != null and cursorEventId != null\">\n            AND (\n                event_time &lt; #{cursorEventTime}\n                OR (\n                    event_time = #{cursorEventTime}\n                    AND event_id &lt; #{cursorEventId, javaType=java.util.UUID, jdbcType=OTHER}\n                )\n            )\n        </if>\n\n        ORDER BY event_time DESC, event_id DESC\n        LIMIT #{limit}\n    </select>\n\n    <select id=\"findActualPartitionByEvent\"\n            parameterType=\"com.company.audit.AuditEventKey\"\n            resultType=\"string\">\n        SELECT tableoid::regclass::text\n        FROM app.audit_event\n        WHERE event_id = #{eventId, javaType=java.util.UUID, jdbcType=OTHER}\n          AND event_time = #{eventTime}\n    </select>\n\n    <select id=\"explainSearchByTenantAndTime\"\n            parameterType=\"com.company.audit.AuditEventSearchParam\"\n            resultType=\"string\">\n        EXPLAIN\n        SELECT\n            <include refid=\"AuditEventColumns\"/>\n        FROM app.audit_event\n        WHERE tenant_id = #{tenantId, javaType=java.util.UUID, jdbcType=OTHER}\n          AND event_time &gt;= #{fromTime}\n          AND event_time &lt;  #{toTime}\n        ORDER BY event_time DESC, event_id DESC\n        LIMIT #{limit}\n    </select>\n\n</mapper>\n"
